script:
const ids = ['kennismaking','prompten','lesvoorbereiding','toetsen-feedback','administratie','veilig-en-ethisch','casussen','vibe-start','vibe-bouwen','vibe-delen','vibe-data','vibe-ai'];
const fout = [];
for (const id of ids) {
  await H.ga('#/module/' + id);
  const h1 = H.q('#hoofd .titelblok h1');
  const lessen = H.qa('#hoofd .les').length;
  const teller = H.q('#hoofd #module-teller');
  const titel = h1 ? h1.textContent.trim() : '';
  if (!titel || !lessen || !teller) fout.push(id + ' (titel="' + titel + '", lessen=' + lessen + ', teller=' + (teller ? 'ja' : 'nee') + ')');
}
await H.ga('#/');
return { ok: fout.length === 0, detail: fout.length ? 'stuk: ' + fout.join(' | ') : ids.length + ' modules renderen elk een titel, minstens een les en de teller' };

const ids = ['a1','a2','a3','b1','b2','b3'];
const fout = [];
for (const id of ids) {
  await H.ga('#/workshop/' + id);
  const code = H.q('#hoofd .titelblok .code.groot');
  const blokken = H.qa('#hoofd .blokken .blok').length;
  const bundel = H.q('#hoofd a[href="#/bundel/' + id + '"]');
  const tekst = code ? code.textContent.trim() : 'geen';
  if (tekst.toLowerCase() !== id || blokken < 9 || !bundel)
    fout.push(id + ' (code="' + tekst + '", blokken=' + blokken + ', bundellink=' + (bundel ? 'ja' : 'nee') + ')');
}
await H.ga('#/');
return { ok: fout.length === 0, detail: fout.length ? 'stuk: ' + fout.join(' | ') : '6 draaiboeken met de juiste code, 9 of meer blokken en een bundellink' };

const gevallen = ['#/module','#/workshop','#/bundel','#/module/bestaat-niet','#/workshop/a9','#/bundel/xyz','#/onzin','#/module/a1','#/workshop/prompten'];
const fout = [];
for (const h of gevallen) {
  await H.ga(h);
  const kop = H.q('#hoofd .kaart.leeg h1');
  const gezien = kop ? kop.textContent.trim() : (H.q('#hoofd .onthaal') ? 'de startpagina' : 'iets anders');
  if (gezien !== 'Niet gevonden') fout.push(h + ' toont ' + gezien);
}
await H.ga('#/');
return { ok: fout.length === 0, detail: fout.length ? fout.join(' | ') : gevallen.length + ' ongeldige hashes tonen allemaal "Niet gevonden"' };

const gevallen = [
  ['#/workshop/A1', '#hoofd a[href="#/bundel/a1"]'],
  ['#/workshop/B3', '#hoofd a[href="#/bundel/b3"]'],
  ['#/module/Prompten', '#hoofd .verder a[href="#/module/lesvoorbereiding"]'],
  ['#/module/VIBE-START', '#hoofd .verder a[href="#/module/vibe-bouwen"]'],
  ['#/bundel/A3', '#hoofd .bundel a[href="#/workshop/a3"]'],
];
const fout = [];
for (const paar of gevallen) {
  await H.ga(paar[0]);
  const kop = H.q('#hoofd .kaart.leeg h2');
  if (!H.q(paar[1])) fout.push(paar[0] + ' geeft ' + (kop ? '"' + kop.textContent.trim() + '"' : 'een pagina zonder ' + paar[1]));
}
await H.ga('#/');
return { ok: fout.length === 0, detail: fout.length ? fout.join(' | ') : '5 hashes met hoofdletters komen op de juiste pagina uit' };

const gevallen = [
  ['#/workshop/a1', 'AI in de klas', 'Vibe coden'],
  ['#/workshop/b2', 'Vibe coden', 'AI in de klas'],
  ['#/module/casussen', 'AI in de klas', 'Vibe coden'],
  ['#/module/vibe-delen', 'Vibe coden', 'AI in de klas'],
];
const fout = [];
for (const g of gevallen) {
  await H.ga(g[0]);
  const kr = H.q('#hoofd .kruimels');
  const t = kr ? kr.textContent.replace(/\s+/g, ' ').trim() : 'geen kruimels';
  if (!t.includes('Overzicht') || !t.includes(g[1]) || t.includes(g[2])) fout.push(g[0] + ' -> "' + t + '"');
}
await H.ga('#/');
return { ok: fout.length === 0, detail: fout.length ? fout.join(' | ') : 'vier kruimelpaden noemen het juiste spoor en niet het andere' };

const gevallen = [
  ['#/', 'home', '.onthaal'],
  ['#/module/prompten', 'module', '.les'],
  ['#/workshop/a1', 'workshop', '.blokken .blok'],
  ['#/bundel/a1', 'bundel', '.bundel .bundel-kop'],
  ['#/prompts', 'prompts', '.promptblok'],
  ['#/gids', 'gids', '.gids-faq'],
  ['#/onzin', 'onbekend', '.kaart.leeg'],
];
const fout = [];
for (const g of gevallen) {
  if (location.hash !== g[0]) await H.ga(g[0]);
  const p = document.body.dataset.pagina;
  const el = H.q('#hoofd ' + g[2]);
  if (p !== g[1] || !el) fout.push(g[0] + ' -> data-pagina="' + p + '" (verwacht "' + g[1] + '"), ' + g[2] + (el ? ' gevonden' : ' ONTBREEKT'));
}
await H.ga('#/');
return { ok: fout.length === 0, detail: fout.length ? fout.join(' | ') : 'zeven routes renderen hun eigen inhoud en zetten body.dataset.pagina juist' };

const gevallen = [
  ['#/module/prompten', '#/module/kennismaking', '#/module/lesvoorbereiding'],
  ['#/module/vibe-bouwen', '#/module/vibe-start', '#/module/vibe-delen'],
  ['#/module/administratie', '#/module/toetsen-feedback', '#/module/veilig-en-ethisch'],
];
const fout = [];
for (const g of gevallen) {
  await H.ga(g[0]);
  const links = H.qa('#hoofd .verder a').map((a) => ({ h: a.getAttribute('href'), t: a.textContent.replace(/\s+/g, ' ').trim() }));
  const v = links.find((l) => l.t.includes('Vorige:'));
  const n = links.find((l) => l.t.includes('Volgende:'));
  if (links.length !== 2 || !v || !n || v.h !== g[1] || n.h !== g[2] || links[0] !== v || links[1] !== n)
    fout.push(g[0] + ' -> ' + (links.map((l) => l.h + ' "' + l.t + '"').join(' + ') || 'geen enkele link'));
}
await H.ga('#/');
return { ok: fout.length === 0, detail: fout.length ? fout.join(' | ') : 'drie modules tonen vorige en volgende uit hun eigen spoor, in die volgorde' };

const { MODULES } = await import('/js/cursus.js');
const fout = [];
// Welke module voor casussen komt, hangt af van de volgorde in MODULES. Die
// verschuift zodra er een module bij komt, dus leiden we hem af in plaats van
// hem hier te herhalen.
const spoorAi = MODULES.filter((m) => m.spoor === 'ai').map((m) => m.id);
const voorCasussen = spoorAi[spoorAi.indexOf('casussen') - 1];
const lees = () => H.qa('#hoofd .verder a').map((a) => ({ h: a.getAttribute('href'), t: a.textContent.replace(/\s+/g, ' ').trim() }));

await H.ga('#/module/kennismaking');
let l = lees();
if (l.some((x) => x.t.includes('Vorige:'))) fout.push('kennismaking heeft toch een vorige');
if (!l.length || l[0].h !== '#/') fout.push('kennismaking begint niet met een link naar het overzicht (' + l.map((x) => x.h).join(',') + ')');
if (!l.some((x) => x.h === '#/module/prompten')) fout.push('kennismaking mist de volgende module');

await H.ga('#/module/casussen');
l = lees();
if (l.some((x) => x.t.includes('Volgende:'))) fout.push('casussen (laatste van spoor ai) heeft toch een volgende');
if (l.some((x) => x.h && x.h.indexOf('#/module/vibe') === 0)) fout.push('casussen springt door naar het vibe-spoor');
if (!l.some((x) => x.h === '#/module/' + voorCasussen)) fout.push('casussen mist de vorige module (' + voorCasussen + ')');

await H.ga('#/module/vibe-start');
l = lees();
if (l.some((x) => x.t.includes('Vorige:'))) fout.push('vibe-start heeft toch een vorige');
if (l.some((x) => x.h === '#/module/casussen')) fout.push('vibe-start springt terug naar het ai-spoor');
if (!l.some((x) => x.h === '#/module/vibe-bouwen')) fout.push('vibe-start mist de volgende module');

await H.ga('#/module/vibe-voorbeeld');
l = lees();
if (l.some((x) => x.t.includes('Volgende:'))) fout.push('vibe-voorbeeld (laatste van spoor vibe) heeft toch een volgende');
if (!l.some((x) => x.h === '#/module/vibe-ai')) fout.push('vibe-voorbeeld mist de vorige module');

await H.ga('#/');
return { ok: fout.length === 0, detail: fout.length ? fout.join(' | ') : 'eerste module van elk spoor zonder vorige, laatste zonder volgende, geen sprong tussen de sporen' };

const meet = () => ({
  blok: H.qa('#hoofd .blokken .blok').length,
  draaiboek: H.qa('#hoofd .draaiboek').length,
  modulelink: H.qa('#hoofd .module-link').length,
  actie: H.qa('#hoofd [data-actie]').length,
});
await H.ga('#/workshop/a3');
const eerst = meet();
await H.ga('#/');
await H.ga('#/module/casussen');
await H.ga('#/workshop/a3');
const nu = meet();
const idsW = H.qa('#hoofd [id]').map((e) => e.id);
const dubbelW = idsW.filter((x, i) => idsW.indexOf(x) !== i);
await H.ga('#/module/prompten');
const idsM = H.qa('#hoofd [id]').map((e) => e.id);
const dubbelM = idsM.filter((x, i) => idsM.indexOf(x) !== i);
await H.ga('#/');
const gelijk = JSON.stringify(eerst) === JSON.stringify(nu);
return {
  ok: gelijk && eerst.draaiboek === 1 && eerst.blok > 0 && dubbelW.length === 0 && dubbelM.length === 0,
  detail: 'A3 eerst ' + JSON.stringify(eerst) + ', na heen en weer ' + JSON.stringify(nu) + '; dubbele ids op het draaiboek: ' + (dubbelW.join(',') || 'geen') + ', op de module: ' + (dubbelM.join(',') || 'geen'),
};

await H.ga('#/module/prompten');
window.scrollTo({ top: 1500, behavior: 'instant' });
await H.wacht(150);
const voor = Math.round(window.scrollY);
await H.ga('#/module/lesvoorbereiding');
const na = Math.round(window.scrollY);
await H.wacht(150);
const later = Math.round(window.scrollY);
await H.ga('#/');
return {
  ok: voor > 200 && na === 0 && later === 0,
  detail: 'de module stond op ' + voor + 'px gescrold, meteen na de routewissel ' + na + 'px en even later ' + later + 'px',
};

if (location.hash !== '#/') await H.ga('#/');
const hrefs = [...new Set(H.qa('#hoofd a[href^="#/"]').map((a) => a.getAttribute('href')))];
const fout = [];
for (const h of hrefs) {
  if (location.hash !== h) await H.ga(h);
  const kop = H.q('#hoofd .kaart.leeg h2');
  if (kop && kop.textContent.trim() === 'Niet gevonden') fout.push(h);
}
await H.ga('#/');
return {
  ok: hrefs.length >= 20 && fout.length === 0,
  detail: hrefs.length + ' unieke links op de startpagina gevolgd, kapot: ' + (fout.join(', ') || 'geen'),
};

const bronnen = ['#/prompts', '#/workshop/a3', '#/bundel/a3'];
const hrefs = new Set();
for (const b of bronnen) {
  await H.ga(b);
  H.qa('#hoofd a[href^="#/"]').forEach((a) => hrefs.add(a.getAttribute('href')));
}
const lijst = [...hrefs];
const fout = [];
for (const h of lijst) {
  if (location.hash !== h) await H.ga(h);
  const kop = H.q('#hoofd .kaart.leeg h2');
  if (kop && kop.textContent.trim() === 'Niet gevonden') fout.push(h);
}
await H.ga('#/');
return {
  ok: lijst.length >= 10 && fout.length === 0,
  detail: lijst.length + ' unieke links vanuit de promptkaart, draaiboek A3 en bundel A3 gevolgd, kapot: ' + (fout.join(', ') || 'geen'),
};

node --input-type=module -e "
import { readFileSync } from 'node:fs';
const bron = readFileSync('./js/app.js', 'utf8');
const m = bron.match(/startuur: (\/.+?\/)\.test\(data\.startuur\)/);
if (!m) { console.log('FOUT: geen startuur-validatie gevonden in laadOpslag()'); process.exit(0); }
const re = new RegExp(m[1].slice(1, -1));
const proeven = [['09:00',true],['00:00',true],['13:30',true],['23:59',true],['25:99',false],['24:00',false],['geen uur',false],['9:00',false],['0900',false],['09:60',false],['09:00 ',false],[12,false],[null,false],[undefined,false],['',false]];
let fout = 0;
for (const [waarde, verwacht] of proeven) {
  const uit = re.test(waarde);
  if (uit !== verwacht) { console.log('FOUT bij', JSON.stringify(waarde), '->', uit, 'verwacht', verwacht); fout++; }
}
console.log('regex:', m[1], '|', proeven.length, 'waarden getest');
console.log(fout ? 'FOUT: ' + fout + ' startuurwaarden worden verkeerd beoordeeld' : 'OK');
"

node --input-type=module -e "
import { MODULES, TOTAAL_LESSEN } from './js/cursus.js';
const sleutels = MODULES.flatMap(m => m.lessen.map(l => m.id + '/' + l.id));
const uniek = new Set(sleutels);
const moduleIds = MODULES.map(m => m.id);
let fout = 0;
if (uniek.size !== TOTAAL_LESSEN) { console.log('FOUT dubbele lessleutel:', sleutels.filter((s,i) => sleutels.indexOf(s) !== i)); fout++; }
if (new Set(moduleIds).size !== moduleIds.length) { console.log('FOUT dubbel module-id'); fout++; }
for (const s of sleutels) if (s !== s.toLowerCase() || s.split('/').length !== 2) { console.log('FOUT rare lessleutel', s); fout++; }
console.log('lessleutels', sleutels.length, '| uniek', uniek.size, '| TOTAAL_LESSEN', TOTAAL_LESSEN, '| modules', moduleIds.length);
console.log(fout ? 'FOUT: de teller bovenaan kan nooit ' + TOTAAL_LESSEN + '/' + TOTAAL_LESSEN + ' bereiken' : 'OK');
"

voorbereiding:
Zet vóór de herlaad in de console:
localStorage.setItem('ai-voor-leerkrachten', JSON.stringify({begeleider:true, startuur:'25:99', afgewerkt:'kennismaking/eerste-gesprek', sessieStart: Date.now() - 7*3600000})); location.hash='#/workshop/a1'; location.reload();
(afgewerkt is bewust een string in plaats van een array, en sessieStart is zeven uur oud.)

script:
const opstart = H.q('.kaart.leeg.opstart');
const veld = H.q('#startuur');
const eerste = H.q('.blokken .blok .blok-tijd strong');
const teller = H.q('.voortgang-mini > span');
const sessie = H.q('[data-actie="sessie"]');
const gemarkeerd = H.qa('.blok.nu, .blok.voorbij').length;
const uur = veld ? veld.value : 'geen veld';
const start = eerste ? eerste.textContent.trim() : 'geen blok';
const t = teller ? teller.textContent.trim() : 'geen teller';
const knoptekst = sessie ? sessie.textContent.trim() : 'geen knop';
const N = (await import('/js/cursus.js')).TOTAAL_LESSEN;
const ok = !opstart && uur === '09:00' && start === '09:00' && t === '0/' + N
  && knoptekst === 'Start sessie' && gemarkeerd === 0;
H.opslagWis();
return { ok, detail: 'startuurveld ' + uur + ', eerste blok ' + start + ', teller ' + t
  + ', sessieknop "' + knoptekst + '", ' + gemarkeerd + ' blokken met nu/voorbij' };

const veld = H.q('#startuur');
const eerste = H.q('.blokken .blok .blok-tijd strong');
const teller = H.q('.voortgang-mini > span');
const sessie = H.q('[data-actie="sessie"]');
const eind = H.q('.eindtijd');
const uur = veld ? veld.value : 'geen veld';
const start = eerste ? eerste.textContent.trim() : 'geen blok';
const t = teller ? teller.textContent.trim() : 'geen teller';
const knoptekst = sessie ? sessie.textContent.trim() : 'geen knop';
const eindtekst = eind ? eind.textContent.trim() : 'geen eindtijd';
const nu = H.qa('.blok.nu').length;
const voorbij = H.qa('.blok.voorbij').length;
const vlag = H.q('.blok.nu .nu-vlag');
const vlagtekst = vlag ? vlag.textContent.trim() : 'geen vlag';
const N = (await import('/js/cursus.js')).TOTAAL_LESSEN;
const ok = uur === '13:30' && start === '13:30' && eindtekst === 'tot 16:30' && t === '2/' + N
  && knoptekst === 'Sessie stoppen' && nu === 1 && voorbij >= 1 && /^nu — nog \d+ min$/.test(vlagtekst);
if (sessie && knoptekst === 'Sessie stoppen') await H.klik(sessie);
const veld2 = H.q('#startuur');
if (veld2) { veld2.value = '09:00'; veld2.dispatchEvent(new Event('change', { bubbles: true })); await H.wacht(50); }
for (const paar of [['kennismaking', 'eerste-gesprek'], ['vibe-delen', 'publiceren']]) {
  await H.ga('#/module/' + paar[0]);
  const k = H.q('.vink[data-sleutel="' + paar[0] + '/' + paar[1] + '"]');
  if (k && k.classList.contains('aan')) await H.klik(k);
}
H.opslagWis();
return { ok, detail: 'startuur ' + uur + ', eerste blok ' + start + ', ' + eindtekst
  + ', teller ' + t + ', sessieknop "' + knoptekst + '", nu=' + nu + ' voorbij=' + voorbij
  + ', vlag "' + vlagtekst + '"' };

const sessie = H.q('[data-actie="sessie"]');
const teller = H.q('.voortgang-mini > span');
const knoptekst = sessie ? sessie.textContent.trim() : 'geen knop';
const t = teller ? teller.textContent.trim() : 'geen teller';
const gemarkeerd = H.qa('.blok.nu, .blok.voorbij').length;
const N = (await import('/js/cursus.js')).TOTAAL_LESSEN;
const ok = knoptekst === 'Start sessie' && gemarkeerd === 0 && t === '1/' + N;
await H.ga('#/module/kennismaking');
const k = H.q('.vink[data-sleutel="kennismaking/wat-is-ai-assistent"]');
if (k && k.classList.contains('aan')) await H.klik(k);
H.opslagWis();
return { ok, detail: 'sessieknop "' + knoptekst + '", ' + gemarkeerd
  + ' blokken met nu/voorbij, teller ' + t + ' (geldige sleutel telt wel mee)' };

const teller = H.q('.voortgang-mini > span');
const vul = H.q('.balk-vul');
const mini = H.q('.voortgang-mini');
const kaart = H.q('a.kaart.module[href="#/module/kennismaking"] .kaart-voet span:last-child');
const t = teller ? teller.textContent.trim() : 'geen teller';
const breedte = vul ? vul.style.width : 'geen balk';
const titel = mini ? mini.getAttribute('title') : 'geen titel';
const kaarttekst = kaart ? kaart.textContent.trim() : 'geen kaart';
const N = (await import('/js/cursus.js')).TOTAAL_LESSEN;
const ok = t === '0/' + N && breedte === '0%' && titel === '0 van ' + N + ' lessen afgewerkt'
  && kaarttekst === '0/2 lessen';
H.opslagWis();
return { ok, detail: 'teller ' + t + ', balk ' + breedte + ', titel "' + titel
  + '", modulekaart kennismaking "' + kaarttekst + '"' };

const lees = () => Number((H.q('.voortgang-mini > span').textContent.trim().split('/')[0]));
const optie = H.q('[data-quiz] .optie');
await H.klik(optie);
const quiz = H.q('[data-quiz]');
quiz.dataset.merk = 'sentinel';
const quizBeantwoord = quiz.classList.contains('beantwoord');
const uitslagVoor = H.q('[data-quiz] .quiz-uitslag').textContent.trim();
const voor = lees();
const knop = H.q('.vink[data-sleutel="kennismaking/wat-is-ai-assistent"]');
await H.klik(knop);
const na = {
  aan: knop.classList.contains('aan'),
  aria: knop.getAttribute('aria-pressed'),
  tekst: knop.textContent.trim(),
  les: knop.closest('.les').classList.contains('af'),
  mod: H.q('#module-teller').textContent.trim(),
  top: lees(),
  merk: H.q('[data-quiz]').dataset.merk,
  quiz: H.q('[data-quiz]').classList.contains('beantwoord'),
  uitslag: H.q('[data-quiz] .quiz-uitslag').textContent.trim(),
};
const ok = quizBeantwoord && uitslagVoor.length > 0 && na.aan === true && na.aria === 'true'
  && na.tekst === '✓ Afgewerkt' && na.les === true && na.mod === '1/2 afgewerkt'
  && na.top === voor + 1 && na.merk === 'sentinel' && na.quiz === true
  && na.uitslag === uitslagVoor;
if (knop.classList.contains('aan')) await H.klik(knop);
H.opslagWis();
return { ok, detail: 'knop "' + na.tekst + '" aria-pressed=' + na.aria + ', les.af=' + na.les
  + ', #module-teller "' + na.mod + '", kopteller ' + voor + ' -> ' + na.top
  + ', quiz bleef beantwoord=' + na.quiz + ' (uitslag "' + na.uitslag + '"), sentinel=' + na.merk };

const casus = H.q('[data-casus]');
const knopC = casus.querySelector('[data-actie="casus"]');
await H.klik(knopC);
const open1 = casus.classList.contains('open');
const aria1 = knopC.getAttribute('aria-expanded');
const tekst1 = knopC.textContent.trim();
const zichtbaar1 = H.zichtbaar(casus.querySelector('.casus-antwoord'));
casus.dataset.merk = 'sentinel';
const lees = () => Number((H.q('.voortgang-mini > span').textContent.trim().split('/')[0]));
const voor = lees();
const knop = H.q('.vink[data-sleutel="casussen/casus-privacy"]');
await H.klik(knop);
const casus2 = H.q('[data-casus]');
const na = {
  open: casus2.classList.contains('open'),
  merk: casus2.dataset.merk,
  zelfdeKnop: casus2.querySelector('[data-actie="casus"]') === knopC,
  aria: casus2.querySelector('[data-actie="casus"]').getAttribute('aria-expanded'),
  mod: H.q('#module-teller').textContent.trim(),
  top: lees(),
  lesAf: knop.closest('.les').classList.contains('af'),
};
const ok = open1 && aria1 === 'true' && tekst1 === 'Verberg het oordeel' && zichtbaar1
  && na.open === true && na.merk === 'sentinel' && na.zelfdeKnop === true && na.aria === 'true'
