  treffers.push({ pad, beide: gpt && cl, toolKader, uitsnede: tekst.slice(Math.max(0, pos - 60), pos + 90).replace(/\s+/g, " ") });
}
for (const m of [...MODULES_AI, MODULE_CASUSSEN])
