        });
        else kijk(m.id + "/" + l.id + " blok" + bi + "." + veld, waarde, toolKader);
      }
    }
for (const s of GIDS_SECTIES) { kijk("gids/" + s.id + ".inleiding", s.inleiding, false); s.punten.forEach((p, i) => { kijk("gids/" + s.id + ".punt" + i + ".kop", p.kop, false); kijk("gids/" + s.id + ".punt" + i + ".tekst", p.tekst, false); }); }
for (const g of FAQ_GROEPEN) g.vragen.forEach((v, i) => { kijk("faq/" + g.titel + "[" + i + "].vraag", v.vraag, false); kijk("faq/" + g.titel + "[" + i + "].antwoord", v.antwoord, false); kijk("faq/" + g.titel + "[" + i + "].tip", v.tip, false); });
